                cur = -1
            elif -stop < zt <= -entry:
                cur = 1
        elif cur == 1 and (zt >= -exit or zt <= -stop):
            cur = 0
        elif cur == -1 and (zt <= exit or zt >= stop):
            cur = 0
        pos[t] = cur
    return pos

