widget.solution:
import numpy as np

def trade_log(pos):
    """[(entry index, exit index, side), ...] for each round trip; exit None if still open."""
    log = []; start = None
    for t in range(len(pos)):
        prev = pos[t - 1] if t > 0 else 0
        if pos[t] != 0 and prev == 0:
            start = t
        elif pos[t] == 0 and prev != 0:
            log.append((start, t, int(prev)))
            start = None
    if start is not None:
        log.append((start, None, int(pos[start])))
    return log


def round_trip_pnl(y, x, beta, i, j, side):
    """P&L in pounds of one round trip: side * (change in y - beta * change in x), days i to j."""
    return side * ((y[j] - y[i]) - beta * (x[j] - x[i]))
